package com.ansh.bank.statement.controller;
import com.ansh.bank.common.config.SeedData; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
/** Generate a CSV account statement from current history. */ @RestController @RequestMapping("/api/statements") public class StatementController {private final SeedData d; public StatementController(SeedData d){this.d=d;} /** Download recent movements as CSV. */ @GetMapping(value="/csv",produces="text/csv") public ResponseEntity<String> csv(){var b=new StringBuilder("Date,Description,Direction,Amount\n");d.transactions.forEach(t->b.append(t.date()).append(',').append(t.description()).append(',').append(t.direction()).append(',').append(t.amount()).append('\n'));return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=statement.csv").body(b.toString());} }
